package candidate

func FirstUnique(values []string) (string, bool) {
	if values == nil {
		return "", false
	}

	counts := make(map[string]int)
	for _, v := range values {
		counts[v]++
	}

	for _, v := range values {
		if counts[v] == 1 {
			return v, true
		}
	}

	return "", false
}

package candidate

import (
	"errors"
	"net/http"
	"strconv"
	"time"
)

func ParseRetryAfter(value string, now time.Time) (time.Duration, error) {
	trimmed := value
	for len(trimmed) > 0 && (trimmed[0] == ' ' || trimmed[0] == '\t' || trimmed[0] == '\n' || trimmed[0] == '\r') {
		trimmed = trimmed[1:]
	}
	for len(trimmed) > 0 && (trimmed[len(trimmed)-1] == ' ' || trimmed[len(trimmed)-1] == '\t' || trimmed[len(trimmed)-1] == '\n' || trimmed[len(trimmed)-1] == '\r') {
		trimmed = trimmed[:len(trimmed)-1]
	}

	if len(trimmed) == 0 {
		return 0, errors.New("empty retry-after value")
	}

	// Check if it's a decimal integer
	if isDecimalInteger(trimmed) {
		seconds, err := strconv.ParseInt(trimmed, 10, 64)
		if err != nil {
			return 0, err
		}
		if seconds < 0 {
			return 0, errors.New("negative retry-after value")
		}
		// Check for overflow: max duration is time.Duration(math.MaxInt64)
		// But we need to be careful: seconds * time.Second might overflow
		// time.Second = 1e9 ns
		// Max time.Duration is about 292 years in seconds
		// Let's check if seconds > maxDurationSeconds
		maxSeconds := int64(time.Duration(time.Second) * 0) // This is 0, not helpful
		// Better: check if seconds * 1e9 overflows int64
		// Max int64 is 9223372036854775807
		// 9223372036854775807 / 1e9 = 9223372036.854775807
		// So max seconds is 9223372036
		const maxSeconds = 9223372036
		if seconds > maxSeconds {
			return 0, errors.New("retry-after value overflows duration")
		}
		d := time.Duration(seconds) * time.Second
		if d <= 0 {
			return 0, nil
		}
		return d, nil
	}

	// Try to parse as HTTP date
	t, err := http.ParseTime(trimmed)
	if err != nil {
		return 0, errors.New("invalid retry-after value")
	}

	d := t.Sub(now)
	if d <= 0 {
		return 0, nil
	}
	return d, nil
}

func isDecimalInteger(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}
